(1, 'Blé tendre hiver', 0, 2150, -4, 500, 15, 22, 30, 't_base: https://www.isagri.fr/ressources/articles/temps-thermique-lindicateur-cl%C3%A9-de-pr%C3%A9vision-des-stades-de-culture ; gdd: https://farmergrows.com/heat-units-gdd-calculator/ ; gel: https://fiches.arvalis-infos.fr/fiche_accident/fiches_accidents.php?mode=fa&type_cul=1&type_acc=5&id_acc=67 ; eau: https://www.arvalis.fr/infos-techniques/declencher-lirrigation-au-bon-moment ; T°opt: https://farmergrows.com/heat-units-gdd-calculator/ ; stress: https://climatology.edpsciences.org/articles/climat/full_html/2019/01/climat201916p129/climat201916p129.html ; NOTE: Vernalisation absente du référentiel (15-60 j entre 3 et 10 °C).'),
(2, 'Orge hiver', 0, 1900, -5, 450, 12, 20, 30, 't_base: https://www.larousse.fr/archives/agricole/page/402 ; gdd: https://www.larousse.fr/archives/agricole/page/402 ; gel: https://www.lgseeds.fr/orge.html ; eau: https://www.arvalis.fr/infos-techniques/irrigation-des-cereales-tout-va-dependre-de-levolution-du-climat ; T°opt: https://fr.jardineriaon.com/culture-d''orge.html ; stress: https://www.reussir.fr/grandes-cultures/moisson-2025-quels-impacts-du-pic-de-chaleur-actuel-sur-les-cereales-paille'),
(3, 'Colza hiver', 5, 2200, -5, 450, 12, 22, 27, 't_base: https://www.isagri.fr/ressources/articles/temps-thermique-lindicateur-cl%C3%A9-de-pr%C3%A9vision-des-stades-de-culture ; gdd: https://www.semae-pedagogie.org/sujet/implantation-et-developpement/ ; gel: https://www.yara.fr/fertilisation/solutions-pour-cultures/colza/agronomie-colza/ ; eau: https://www.lat-nitrogen.com/fr/fr/crop/winter-rapeseed--15 ; T°opt: https://www.yara.fr/fertilisation/solutions-pour-cultures/colza/agronomie-colza/ ; stress: https://www.terresinovia.fr/fr/informations-techniques/adaptation-au-changement-climatique'),
(4, 'Maïs grain', 6, 1600, 0, 600, 20, 30, 35, 't_base: https://www.arvalis.fr/infos-techniques/les-cles-pour-optimiser-les-semis-de-mais ; gdd: https://www.arvalis.fr/infos-techniques/le-mais-grain-une-alternative-aux-cultures-dhiver-non-semees ; gel: https://fiches.arvalis-infos.fr/fiche_accident/fiches_accidents.php?mode=fa&type_cul=3&type_acc=5&id_acc=327 ; eau: https://www.perspectives-agricoles.com/conduite-de-cultures/modelisation-des-besoins-en-eau-combien-consomment-les-cultures ; T°opt: https://www.perspectives-agricoles.com/recherche-agronomie/les-fortes-chaleurs-penalisent-le-potentiel-des-mais ; stress: https://www.arvalis.fr/infos-techniques/mais-quels-impacts-des-fortes-temperatures-et-du-manque-deau'),
