(6, 'Soja', 10, 1500, 0, 550, 20, 30, 35, 't_base: https://www.trackgdd.com/guides/gdd-base-temperatures ; gdd: https://www.larousse.fr/archives/agricole/page/524 ; gel: https://www.pioneer.com/us/agronomy/Effects-Cold-Temperatures-Following-Soybean-Planting.html ; eau: https://www.agriculture-dromoise.fr/articles/irriguer-le-soja-avec-peu-d-eau-29600/ ; T°opt: https://www.agriculture-dromoise.fr/articles/irriguer-le-soja-avec-peu-d-eau-29600/ ; stress: https://www.agriculture-dromoise.fr/articles/irriguer-le-soja-avec-peu-d-eau-29600/'),
(7, 'Betterave sucrière', 3, 2400, -4, 650, 18, 22, 30, 't_base: https://www.sciencedirect.com/science/article/abs/pii/S0378429014000616 ; gdd: https://cmgp-cas.com/cultures/grandes-cultures/betterave-sucriere/ ; gel: https://www.irbab-kbivb.be/fr/refroidissement-et-gel-pensez-a-la-recolte-de-vos-betteraves-sucrieres/ ; eau: https://www.isagri.fr/ressources/articles/irrigation-quelle-quantit%C3%A9-deau-pour-assurer-de-bons-rendements- ; T°opt: https://cmgp-cas.com/cultures/grandes-cultures/betterave-sucriere/ ; stress: https://www.sesvanderhave.com/fr/nos-recherches-et-innovations/tol%C3%A9rance-%C3%A0-la-secheresse'),
(8, 'Pomme de terre', 7, 1500, -2, 600, 15, 20, 28, 't_base: https://terra-potager.com/les-zeros-de-vegetation-par-legume/ ; gdd: https://www.fao.org/land-water/databases-and-software/crop-information/potato/en/ ; gel: https://fiches.arvalis-infos.fr/fiche_accident/fiches_accidents.php?mode=fa&type_cul=3&type_acc=5&id_acc=327 ; eau: https://www.fao.org/4/a1336f/a1336f00.pdf ; T°opt: https://www.fao.org/4/x6083f/x6083f08.htm ; stress: https://www.researchgate.net/publication/40105176_Responses_of_the_Potato_Plant_to_Temperature ; NOTE: A VERIFIER : lien gel identique à celui du maïs.'),
(9, 'Vigne (raisin de cuve)', 10, 1300, -2, 400, 25, 30, 35, 't_base: https://www.vignevin.com/article/comment-suivre-le-risque-gel/ ; gdd: https://oregonviticulture.net/gdd/gdd.html ; gel: https://ephytia.inrae.fr/fr/C/7062/Vigne-Gelees ; eau: https://www.inrae.fr/dossiers/quels-vins-demain/bataille-leau ; T°opt: https://www.picturethisai.com/fr/care/temperature/Vitis_vinifera.html ; stress: https://vignevin-charentes.com/wp-content/uploads/2024/01/5-Conduite-de-la-vigne-preparation-des-vendanges-et-aleas-climatiques-part-11.pdf ; NOTE: Seuil gel dépend du stade (dormant -8, coton -8 à -2, pointe verte -2 à 0).'),
(10, 'Olivier', 10, NULL, -8, 300, 25, 32, 40, 't_base: https://www.franceolive.fr/categorie/connaissance-de-l-arbre/presentation-de-l-arbre ; gdd: non sourcé ; gel: https://www.visionhabitats.fr/2026/05/28/proteger-olivier-gel/ ; eau: https://www.franceolive.fr/categorie/connaissance-de-l-arbre/presentation-de-l-arbre ; T°opt: https://www.picturethisai.com/fr/care/temperature/Olea_europaea.html ; stress: https://wikifarmer.com/library/fr/article/comment-prot%C3%A9ger-les-oliviers-de-la-chaleur-et-de-la-s%C3%A9cheresse-pendant-d%C3%A9t%C3%A9 ; NOTE: GDD non défini (pérenne).');
